BEGIN READ ONLY;SET LOCAL statement_timeout='15s';SELECT jsonb_build_object('readOnly',current_setting('transaction_read_only'),'functions',(SELECT jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'acl',p.proacl,'owner',pg_get_userbyid(p.proowner))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('generate_product_catalog_share_v1','preview_product_catalog_share_v1','import_product_catalog_share_v1'))) metadata;ROLLBACK;